    void **vptr = *((void ***)((char *)ctx + 8));
    if (!vptr) return 0;
    Cb3 fn = (Cb3)vptr[0x48 / sizeof(void*)];
    if (fn) return fn(ctx, arg1, arg2);
    return 0;
}

/* 0x0057EC10: Dispatches callback with 4 arguments */
