    void **vptr = *((void ***)((char *)ctx + 0xc));
    if (!vptr) return 0;
    Cb4 fn = (Cb4)vptr[0x38 / sizeof(void*)];
    void *sub_ctx = *((void **)((char *)ctx + 0x10));
    if (fn) return fn(sub_ctx, a1, a2, a3);
