/* ------------------------------------------------------------------ */
/*  Math helpers                                                        */
/* ------------------------------------------------------------------ */
struct Vec3 { float x, y, z; };
struct Vec4 { float x, y, z, w; };
struct Mat4 { float m[4][4]; };

static inline Vec3 vec3_sub(const Vec3 &a, const Vec3 &b) {
    return { a.x-b.x, a.y-b.y, a.z-b.z };
}
static inline float vec3_length(const Vec3 &v) {
    return sqrtf(v.x*v.x + v.y*v.y + v.z*v.z);
}
static inline Vec3 vec3_normalize(const Vec3 &v) {
    float l = vec3_length(v);
    if (l < 1e-6f) return {0,0,1};
    return { v.x/l, v.y/l, v.z/l };
}
static inline Vec3 vec3_cross(const Vec3 &a, const Vec3 &b) {
    return { a.y*b.z - a.z*b.y,
             a.z*b.x - a.x*b.z,
             a.x*b.y - a.y*b.x };
}

/* ------------------------------------------------------------------ */
/*  HRenderVisual base                                                  */
/* ------------------------------------------------------------------ */
class HRenderVisual {
public:
    THRASHTEXTURE *mpTexture;
    unsigned int   mColour;     /* ARGB8888 */
    bool           mVisible;

    HRenderVisual() : mpTexture(nullptr), mColour(0xFFFFFFFF), mVisible(true) {}
    virtual ~HRenderVisual() {}
    virtual void Render(const Mat4 &viewProj) = 0;
    virtual void Update(float dt) { (void)dt; }
};

/* ------------------------------------------------------------------ */
/*  RBillBoard — screen-aligned billboard                              */
/* ------------------------------------------------------------------ */
class RBillBoard : public HRenderVisual {
public:
    Vec3  mWorldPos;    /* billboard world-space position              */
    float mWidth;       /* half-width in world units                   */
    float mHeight;      /* half-height in world units                  */

    /* Screen-space projection: assume viewport is set up by THRASH   */
    float mScreenX, mScreenY; /* projected centre (pixels)            */
    float mScreenW, mScreenH; /* projected half-size (pixels)         */
    float mDepth;             /* z after projection [0,1]             */

    RBillBoard()
        : mWorldPos{0,0,0}, mWidth(1.f), mHeight(1.f),
          mScreenX(0), mScreenY(0), mScreenW(16), mScreenH(16), mDepth(0.5f)
    {}

    /* ---- Project world position to screen space ---- */
    void Project(const Mat4 &viewProj, float vpW, float vpH) {
        /* Transform world pos by view-projection matrix */
        float px = viewProj.m[0][0]*mWorldPos.x + viewProj.m[0][1]*mWorldPos.y
                 + viewProj.m[0][2]*mWorldPos.z  + viewProj.m[0][3];
        float py = viewProj.m[1][0]*mWorldPos.x + viewProj.m[1][1]*mWorldPos.y
                 + viewProj.m[1][2]*mWorldPos.z  + viewProj.m[1][3];
        float pz = viewProj.m[2][0]*mWorldPos.x + viewProj.m[2][1]*mWorldPos.y
                 + viewProj.m[2][2]*mWorldPos.z  + viewProj.m[2][3];
        float pw = viewProj.m[3][0]*mWorldPos.x + viewProj.m[3][1]*mWorldPos.y
                 + viewProj.m[3][2]*mWorldPos.z  + viewProj.m[3][3];

        if (pw < 0.0001f) { mVisible = false; return; }
        mVisible = true;

        float inv_w = 1.f / pw;
        float ndcX  = px * inv_w;   /* [-1, 1] */
        float ndcY  = py * inv_w;   /* [-1, 1] */

        /* NDC → screen pixels (THRASH origin: top-left) */
        mScreenX = ( ndcX + 1.f) * 0.5f * vpW;
        mScreenY = (-ndcY + 1.f) * 0.5f * vpH;
        mDepth   = pz * inv_w * 0.5f + 0.5f;

        /* Project size: billboard size in pixels at this depth */
        mScreenW = mWidth  * inv_w * vpW * 0.5f;
        mScreenH = mHeight * inv_w * vpH * 0.5f;
    }

    /* ---- Render ---- */
    void Render(const Mat4 &viewProj) override {
        if (!mVisible) return;

        /* Bind texture */
        THRASH_settexture(mpTexture);

        /* Build 4 screen-space vertices for the billboard quad.      */
        /* THRASHVERTEX uses pre-transformed coordinates.             */
        float x0 = mScreenX - mScreenW,  x1 = mScreenX + mScreenW;
        float y0 = mScreenY - mScreenH,  y1 = mScreenY + mScreenH;
        float z  = mDepth;
        float w  = 1.f;   /* already projected: w = 1 for XYZRHW   */

        THRASHVERTEX v[4];

        /* Top-left */
        v[0].x = x0; v[0].y = y0; v[0].z = z; v[0].w = w;
        v[0].color    = mColour;
        v[0].specular = 0xFF000000;
        v[0].u = 0.f; v[0].v = 0.f;

        /* Top-right */
        v[1].x = x1; v[1].y = y0; v[1].z = z; v[1].w = w;
        v[1].color    = mColour;
        v[1].specular = 0xFF000000;
        v[1].u = 1.f; v[1].v = 0.f;

        /* Bottom-right */
        v[2].x = x1; v[2].y = y1; v[2].z = z; v[2].w = w;
        v[2].color    = mColour;
        v[2].specular = 0xFF000000;
        v[2].u = 1.f; v[2].v = 1.f;

        /* Bottom-left */
        v[3].x = x0; v[3].y = y1; v[3].z = z; v[3].w = w;
        v[3].color    = mColour;
        v[3].specular = 0xFF000000;
        v[3].u = 0.f; v[3].v = 1.f;

        /* Enable alpha blending for sprites */
        THRASH_setstate(THRASH_STATE_ALPHA, THRASH_ALPHA_DEFAULT);
        THRASH_setstate(THRASH_STATE_CULL,  THRASH_CULL_NONE);

        /* Draw as two triangles (split the quad) */
        THRASH_drawtri(&v[0], &v[1], &v[2]);
        THRASH_drawtri(&v[0], &v[2], &v[3]);

        /* Restore state */
        THRASH_setstate(THRASH_STATE_ALPHA, THRASH_ALPHA_NONE);
    }

    /* ---- Accessors ---- */
    void SetTexture(THRASHTEXTURE *tex) { mpTexture = tex; }
    void SetPosition(float x, float y, float z) { mWorldPos = {x,y,z}; }
    void SetSize(float w, float h) { mWidth = w; mHeight = h; }
    void SetColour(unsigned int argb) { mColour = argb; }
};

/*
 * RCustomLayers.cpp  —  D:\NFS\Nfs5\game\Common\Render\RCustomLayers.cpp
 *
 * Custom render layer stack for transparent/overlay geometry.
 * Reconstructed from Porsche.exe embedded error string:
 *   "RenderControl::BackFaceCullPrimitive, Invalid mPrimType!"
 */

#ifdef _WIN32
#  include <windows.h>
#else
#  include "../compat/win32_compat.h"
#endif

#include <cstdio>
#include <cstring>
#include "../../thrash/thrash.h"

/* ------------------------------------------------------------------ */
/*  Primitive type enum (matches THRASH draw function variants)        */
/* ------------------------------------------------------------------ */
enum PrimType {
    PRIM_TRIANGLES  = 0,
    PRIM_TRISTRIP   = 1,
    PRIM_TRIFAN     = 2,
    PRIM_QUADS      = 3,
    PRIM_LINES      = 4,
    PRIM_POINTS     = 5,
    PRIM_SPRITES    = 6,
    PRIM_TYPE_MAX   = 7
};

/* ------------------------------------------------------------------ */
/*  Render layer descriptor                                             */
/* ------------------------------------------------------------------ */
struct RenderLayer {
    int              state_alpha;
    int              state_cull;
    int              state_depth;
    int              state_filter;
    THRASHTEXTURE   *texture;
    THRASHVERTEX    *verts;
    int              vert_count;
    PrimType         prim_type;
    int              stride;
    bool             active;
};

#define MAX_LAYERS 64

/* ------------------------------------------------------------------ */
/*  RenderControl — manages the layer stack                            */
/* ------------------------------------------------------------------ */
class RenderControl {
public:
    RenderLayer  mLayers[MAX_LAYERS];
    int          mLayerCount;
    PrimType     mPrimType;        /* current active primitive type */
    int          mCullMode;

    RenderControl() : mLayerCount(0), mPrimType(PRIM_TRIANGLES),
                      mCullMode(THRASH_CULL_CCW)
    {
        memset(mLayers, 0, sizeof(mLayers));
    }

    /* ---- Push a new render layer ---- */
    RenderLayer* PushLayer() {
        if (mLayerCount >= MAX_LAYERS) return nullptr;
        RenderLayer *l = &mLayers[mLayerCount++];
        memset(l, 0, sizeof(*l));
        l->active       = true;
        l->state_alpha  = THRASH_getstate(THRASH_STATE_ALPHA);
        l->state_cull   = THRASH_getstate(THRASH_STATE_CULL);
        l->state_depth  = THRASH_getstate(THRASH_STATE_DEPTHBUFFER);
        l->state_filter = THRASH_getstate(THRASH_STATE_FILTER);
        return l;
    }

    /* ---- Pop and discard top layer ---- */
    void PopLayer() {
        if (mLayerCount > 0) {
            mLayers[--mLayerCount].active = false;
        }
    }

    /* ---- Flush all pending layers to THRASH ---- */
    void FlushLayers() {
        for (int i = 0; i < mLayerCount; i++) {
            RenderLayer *l = &mLayers[i];
            if (!l->active || !l->verts || l->vert_count == 0) continue;

            /* Apply layer state */
            THRASH_setstate(THRASH_STATE_ALPHA,       l->state_alpha);
            THRASH_setstate(THRASH_STATE_CULL,        l->state_cull);
            THRASH_setstate(THRASH_STATE_DEPTHBUFFER, l->state_depth);
            THRASH_setstate(THRASH_STATE_FILTER,      l->state_filter);
            THRASH_settexture(l->texture);

            /* Submit geometry */
            DispatchPrimitive(l->prim_type, l->verts,
                              l->vert_count, l->stride);
        }

        /* Restore default state */
        THRASH_setstate(THRASH_STATE_ALPHA, THRASH_ALPHA_NONE);
        THRASH_setstate(THRASH_STATE_CULL,  mCullMode);

        mLayerCount = 0;
    }

    /*
     * BackFaceCullPrimitive — cull based on vertex winding.
     * Error string: "RenderControl::BackFaceCullPrimitive, Invalid mPrimType!"
     *
     * Returns true if the primitive should be rendered (passes cull test).
     */
    bool BackFaceCullPrimitive(THRASHVERTEX *v0, THRASHVERTEX *v1,
                                THRASHVERTEX *v2)
    {
        /* Validate primitive type */
        if (mPrimType < PRIM_TRIANGLES || mPrimType >= PRIM_TYPE_MAX) {
            fprintf(stderr,
                "RenderControl::BackFaceCullPrimitive, Invalid mPrimType!\n");
            return false;
        }

        if (mCullMode == THRASH_CULL_NONE) return true;

        /* 2D cross product of screen-space edge vectors */
        float ax = v1->x - v0->x,  ay = v1->y - v0->y;
        float bx = v2->x - v0->x,  by = v2->y - v0->y;
        float cross = ax * by - ay * bx;

        /* CW = positive cross, CCW = negative cross (screen y flipped) */
        if (mCullMode == THRASH_CULL_CW)  return cross > 0.f;
        if (mCullMode == THRASH_CULL_CCW) return cross < 0.f;
        return true;
    }

    /* ---- Dispatch geometry to THRASH ---- */
    void DispatchPrimitive(PrimType pt, THRASHVERTEX *verts,
                            int count, int stride)
    {
        switch (pt) {
        case PRIM_TRIANGLES:
            THRASH_drawtrimesh(count, verts, stride);
            break;
        case PRIM_TRISTRIP:
            THRASH_drawtristrip(count, verts, stride);
            break;
        case PRIM_TRIFAN:
            THRASH_drawtrifan(count, verts, stride);
            break;
        case PRIM_QUADS:
            THRASH_drawquadmesh(count, verts, stride);
            break;
        case PRIM_LINES:
            THRASH_drawlinemesh(count, verts, stride);
            break;
        case PRIM_POINTS:
            THRASH_drawpointmesh(count, verts, stride);
            break;
        case PRIM_SPRITES:
            THRASH_drawspritemesh(count, verts, stride);
            break;
        default:
            fprintf(stderr,
                "RenderControl::BackFaceCullPrimitive, Invalid mPrimType!\n");
            break;
        }
    }

    /* ---- Accessors ---- */
    void SetCullMode(int mode)    { mCullMode = mode; }
    void SetPrimType(PrimType pt) { mPrimType = pt; }
    int  GetLayerCount() const    { return mLayerCount; }
};

/* Singleton */
static RenderControl g_renderControl;

/* C interface for engine code */
extern "C" {
    RenderControl* RC_get(void)            { return &g_renderControl; }
    void RC_flush(void)                    { g_renderControl.FlushLayers(); }
    void RC_set_cull(int mode)             { g_renderControl.SetCullMode(mode); }
    void RC_set_primtype(int pt)           { g_renderControl.SetPrimType((PrimType)pt); }
    int  RC_cull_tri(THRASHVERTEX *a, THRASHVERTEX *b, THRASHVERTEX *c) {
        return g_renderControl.BackFaceCullPrimitive(a,b,c) ? 1 : 0;
    }
}

