/* \real\patch3\cmn\dyntexture.c */
#include "dyntexture.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_DYN_TEXTURES 512
#define MAX_FORMAT_TYPES 16

struct DynTexture {
    char name[64];
    int width;
    int height;
    int format;
    int mipmaps;
    int is_uploaded;
    THRASHTEXTURE *thrash_tex;
    DynTexture *next;
};

static DynTexture *g_dtex_head = NULL;
static int g_num_textures = 0;
static int g_format_counts[MAX_FORMAT_TYPES] = {0};

int DTEX_init(void)
{
    g_dtex_head = NULL;
    g_num_textures = 0;
    memset(g_format_counts, 0, sizeof(g_format_counts));
    return 1;
}

void DTEX_shutdown(void)
{
    DynTexture *cur = g_dtex_head;
    while (cur) {
        DynTexture *next = cur->next;
        if (cur->thrash_tex) {
            THRASH_tfree(cur->thrash_tex);
        }
        free(cur);
        cur = next;
    }
    g_dtex_head = NULL;
    g_num_textures = 0;
}

DynTexture* DTEX_create(const char *name, int width, int height, int format, int mipmaps)
{
    if (g_num_textures >= MAX_DYN_TEXTURES) {
        fprintf(stderr, "[DTEXTURE] dtexture.c Error too many different texture types used\n Try using more textures of the same width/mipmap levels/ pixel format\n");
        return NULL;
    }

    DynTexture *dt = (DynTexture*)calloc(1, sizeof(DynTexture));
    if (!dt) {
        fprintf(stderr, "D3D Error - Not enough texture memory.\n");
        return NULL;
    }

    if (name) strncpy(dt->name, name, sizeof(dt->name) - 1);
    dt->width = width;
    dt->height = height;
    dt->format = format;
    dt->mipmaps = mipmaps;
    dt->is_uploaded = 0;

    dt->thrash_tex = THRASH_talloc(width, height, format, mipmaps, NULL);
    if (!dt->thrash_tex) {
        fprintf(stderr, "D3D Error - Not enough texture memory.\n");
        free(dt);
        return NULL;
    }

    dt->next = g_dtex_head;
    g_dtex_head = dt;
    g_num_textures++;

    return dt;
}

void DTEX_destroy(DynTexture *dt)
{
    if (!dt) return;

    DynTexture **curr = &g_dtex_head;
    int found = 0;
    while (*curr) {
        if (*curr == dt) {
            *curr = dt->next;
            found = 1;
            break;
        }
        curr = &(*curr)->next;
    }

    if (!found) {
        fprintf(stderr, "DTEX - DTEX_destroy error, texture not in list\n");
        return;
    }

    if (dt->thrash_tex) {
        THRASH_tfree(dt->thrash_tex);
    }
    free(dt);
    g_num_textures--;
}

int DTEX_upload(DynTexture *dt, const void *data, int pitch)
{
    if (!dt) return 0;
    if (dt->is_uploaded) {
        fprintf(stderr, "[DTEX] Error - trying to upload a texture thats already uploaded.\n Texture %s.\n",
                dt->name[0] ? dt->name : "unnamed");
    }

    if (dt->thrash_tex && data) {
        THRASH_tupdate(dt->thrash_tex, (void*)data, pitch);
        dt->is_uploaded = 1;
        return 1;
    }

    return 0;
}

void DTEX_bind(DynTexture *dt)
{
    if (dt && dt->thrash_tex) {
        THRASH_settexture(dt->thrash_tex);
    } else {
        THRASH_settexture(NULL);
    }
}

DynTexture* DTEX_find(const char *name)
{
    if (!name) return NULL;
    for (DynTexture *cur = g_dtex_head; cur != NULL; cur = cur->next) {
        if (strcmp(cur->name, name) == 0) {
            return cur;
        }
    }
    return NULL;
}

/* \real\cmn\loadpack.c */
#include "loadpack.h"
#include "../../engine/file/vfs.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int QFS_decompress_block(const uint8_t *src, size_t src_len, uint8_t *dst, size_t dst_len)
{
    if (!src || !dst || src_len < 4) return 0;
    if (src[1] != 0xFB) return 0;

    int has_large_sz = src[0] & 0x01;
    int has_comp_sz  = src[0] & 0x80;

    size_t in_pos = 2;
    if (has_large_sz) in_pos += 3;
    else in_pos += 2;

    if (has_comp_sz) in_pos += 3;

    size_t out_pos = 0;

    while (in_pos < src_len && out_pos < dst_len) {
        uint8_t byte0 = src[in_pos++];
        if (byte0 >= 0xFC) {
            int lit_len = byte0 & 0x03;
            while (lit_len-- && in_pos < src_len && out_pos < dst_len) {
                dst[out_pos++] = src[in_pos++];
            }
            break;
        } else if (byte0 >= 0xE0) {
            if (in_pos + 3 > src_len) break;
            uint8_t byte1 = src[in_pos++];
            uint8_t byte2 = src[in_pos++];
            uint8_t byte3 = src[in_pos++];
            int lit_len = (byte0 & 0x03);
            int copy_len = (((byte0 & 0x0C) << 6) | byte3) + 5;
            int offset = (((byte0 & 0x10) << 12) | ((int)byte1 << 8) | byte2) + 1;

            while (lit_len-- && in_pos < src_len && out_pos < dst_len) {
                dst[out_pos++] = src[in_pos++];
            }
            while (copy_len-- && out_pos < dst_len) {
                dst[out_pos] = (out_pos >= (size_t)offset) ? dst[out_pos - offset] : 0;
                out_pos++;
            }
        } else if (byte0 >= 0xC0) {
            if (in_pos + 2 > src_len) break;
            uint8_t byte1 = src[in_pos++];
            uint8_t byte2 = src[in_pos++];
            int lit_len = (byte0 & 0x03);
            int copy_len = (byte0 & 0x3C) + 4;
            int offset = (((int)byte1 << 8) | byte2) + 1;

            while (lit_len-- && in_pos < src_len && out_pos < dst_len) {
                dst[out_pos++] = src[in_pos++];
            }
            while (copy_len-- && out_pos < dst_len) {
                dst[out_pos] = (out_pos >= (size_t)offset) ? dst[out_pos - offset] : 0;
                out_pos++;
            }
        } else if (byte0 >= 0x80) {
            if (in_pos + 1 > src_len) break;
            uint8_t byte1 = src[in_pos++];
            int lit_len = (byte1 >> 6) & 0x03;
            int copy_len = (byte0 & 0x1F) + 3;
            int offset = (((byte0 & 0x60) << 3) | (byte1 & 0x3F)) + 1;

            while (lit_len-- && in_pos < src_len && out_pos < dst_len) {
                dst[out_pos++] = src[in_pos++];
            }
            while (copy_len-- && out_pos < dst_len) {
                dst[out_pos] = (out_pos >= (size_t)offset) ? dst[out_pos - offset] : 0;
                out_pos++;
            }
        } else {
            if (in_pos >= src_len) break;
            uint8_t byte1 = src[in_pos++];
            int lit_len = (byte0 & 0x03);
            int copy_len = ((byte0 >> 2) & 0x07) + 3;
            int offset = (((byte0 & 0x60) << 3) | byte1) + 1;

            while (lit_len-- && in_pos < src_len && out_pos < dst_len) {
                dst[out_pos++] = src[in_pos++];
            }
            while (copy_len-- && out_pos < dst_len) {
                dst[out_pos] = (out_pos >= (size_t)offset) ? dst[out_pos - offset] : 0;
                out_pos++;
            }
        }
    }

    return (int)out_pos;
}

uint32_t FILE_unpacksize(const char *filename)
{
    size_t sz = 0;
    uint8_t *raw = (uint8_t*)VFS_ReadFile(filename, &sz);
    if (!raw) {
        fprintf(stderr, "FILE_unpacksize - unable to open file %s\n", filename);
        return 0;
    }

    uint32_t decomp_sz = 0;
    if (sz >= 4 && raw[1] == 0xFB) {
        if (raw[0] & 0x01) {
            decomp_sz = ((uint32_t)raw[2] << 16) | ((uint32_t)raw[3] << 8) | raw[4];
        } else {
            decomp_sz = ((uint32_t)raw[2] << 8) | raw[3];
        }
    } else {
        decomp_sz = (uint32_t)sz;
    }

    VFS_FreeFile(raw);
    return decomp_sz;
}

void* FILE_loadpack(const char *filename)
{
    size_t sz = 0;
    uint8_t *raw = (uint8_t*)VFS_ReadFile(filename, &sz);
    if (!raw) {
        fprintf(stderr, "FILE_loadpack - unable to unpack file %s\n", filename);
        return NULL;
    }

    if (sz >= 4 && raw[1] == 0xFB) {
        uint32_t decomp_sz = 0;
        if (raw[0] & 0x01) {
            decomp_sz = ((uint32_t)raw[2] << 16) | ((uint32_t)raw[3] << 8) | raw[4];
        } else {
            decomp_sz = ((uint32_t)raw[2] << 8) | raw[3];
        }
        uint8_t *decomp = (uint8_t*)malloc(decomp_sz);
        if (!decomp) {
            VFS_FreeFile(raw);
            fprintf(stderr, "FILE_loadpack - unable to unpack file %s\n", filename);
            return NULL;
        }
        QFS_decompress_block(raw, sz, decomp, decomp_sz);
        VFS_FreeFile(raw);
        return decomp;
    }

    return raw;
}

int FILE_loadpackat(const char *filename, void *destination)
{
    if (!destination) return 0;
    size_t sz = 0;
    uint8_t *raw = (uint8_t*)VFS_ReadFile(filename, &sz);
    if (!raw) {
        fprintf(stderr, "FILE_loadpackat - unable to unpack file %s\n", filename);
        return 0;
    }

    if (sz >= 4 && raw[1] == 0xFB) {
        uint32_t decomp_sz = 0;
        if (raw[0] & 0x01) {
            decomp_sz = ((uint32_t)raw[2] << 16) | ((uint32_t)raw[3] << 8) | raw[4];
        } else {
            decomp_sz = ((uint32_t)raw[2] << 8) | raw[3];
        }
        QFS_decompress_block(raw, sz, (uint8_t*)destination, decomp_sz);
        VFS_FreeFile(raw);
        return 1;
    }

    memcpy(destination, raw, sz);
    VFS_FreeFile(raw);
    return 1;
}

/* \real\cmn\stream.c */
#include "stream.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct STREAM {
    uint32_t magic;         /* 'STRM' */
    int      state;         /* STREAM_State */
    int      num_requests;
    int      num_filters;
    int      num_taps;
    int      active_filter;
    int      greedy_level;
    int      priority;
    uint8_t *buffer;
    size_t   buffer_size;
    size_t   buffer_used;
    size_t   read_pos;
    size_t   write_pos;
    int      is_allocated_buf;
};

STREAM* STREAM_create(int requests, int filters, int taps, void *buf, size_t buf_size)
{
    if (buf_size < 0x6000) {
        fprintf(stderr, "STREAM_create - stream buffer too small\n");
        return NULL;
    }
    if (requests < 2) {
        fprintf(stderr, "STREAM_create - a minimum of two requests is required\n");
        return NULL;
    }
    if (requests > 0x100) {
        fprintf(stderr, "STREAM_create - too many requests (%d)\n", requests);
        return NULL;
    }
    if (filters < 1 || filters > 16) {
        fprintf(stderr, "STREAM_create - invalid number of filters (%d)\n", filters);
        return NULL;
    }
    if (taps < 1 || taps > filters) {
        fprintf(stderr, "STREAM_create - invalid number of taps (%d)\n", taps);
        return NULL;
    }

    STREAM *s = (STREAM*)calloc(1, sizeof(STREAM));
    if (!s) return NULL;

    s->magic = STREAM_MAGIC;
    s->num_requests = requests;
    s->num_filters = filters;
    s->num_taps = taps;
    s->active_filter = 0;
    s->state = STREAM_STATE_IDLE;
    s->buffer_size = buf_size;

    if (buf) {
        s->buffer = (uint8_t*)buf;
        s->is_allocated_buf = 0;
    } else {
        s->buffer = (uint8_t*)malloc(buf_size);
        s->is_allocated_buf = 1;
    }

    return s;
}

void STREAM_destroy(STREAM *s)
{
    if (!s) return;
    if (s->is_allocated_buf && s->buffer) {
        free(s->buffer);
    }
    free(s);
}

void STREAM_kill(STREAM *s)
{
    if (!s) return;
    s->state = STREAM_STATE_IDLE;
    s->buffer_used = 0;
    s->read_pos = 0;
    s->write_pos = 0;
}

int STREAM_setfilter(STREAM *s, int filter_num)
{
    if (!s) return 0;
    if (filter_num < 0 || filter_num >= s->num_filters) {
        fprintf(stderr, "STREAM_setfilter - invalid filter number\n");
        return 0;
    }
    if (s->state != STREAM_STATE_IDLE) {
        fprintf(stderr, "STREAM_setfilter - stream must be idle to set filter\n");
        return 0;
    }
    s->active_filter = filter_num;
    return 1;
}

int STREAM_buffersize(STREAM *s)
{
    return s ? (int)s->buffer_size : 0;
}

int STREAM_bufferusage(STREAM *s)
{
    return s ? (int)s->buffer_used : 0;
}

int STREAM_queuefile(STREAM *s, const char *path)
{
    if (!s || !path) return 0;
    FILE *fp = fopen(path, "rb");
    if (!fp) return 0;

    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    if (sz <= 0 || (size_t)sz > s->buffer_size) {
        fclose(fp);
        return 0;
    }

    size_t rd = fread(s->buffer, 1, sz, fp);
    fclose(fp);

    s->buffer_used = rd;
    s->read_pos = 0;
    s->write_pos = rd;
    s->state = STREAM_STATE_ACTIVE;
    return 1;
}

int STREAM_queuemem(STREAM *s, const void *mem, size_t sz)
{
    if (!s || !mem || sz == 0) return 0;
    if (sz > s->buffer_size) sz = s->buffer_size;

    memcpy(s->buffer, mem, sz);
    s->buffer_used = sz;
    s->read_pos = 0;
    s->write_pos = sz;
    s->state = STREAM_STATE_ACTIVE;
    return 1;
}

void* STREAM_get(STREAM *s, size_t *out_sz)
{
    if (!s || s->buffer_used == 0) {
        if (out_sz) *out_sz = 0;
        return NULL;
    }
    if (out_sz) *out_sz = s->buffer_used;
    return s->buffer + s->read_pos;
}

void STREAM_release(STREAM *s, void *chunk)
{
    (void)chunk;
    if (!s) return;
    s->state = STREAM_STATE_IDLE;
    s->buffer_used = 0;
}

int STREAM_cancelrequest(STREAM *s, int request_id)
{
    (void)request_id;
    if (!s) return 0;
    s->state = STREAM_STATE_IDLE;
    return 1;
}

int STREAM_isendofstream(STREAM *s)
{
    if (!s) return 1;
    return (s->read_pos >= s->write_pos);
}

int STREAM_requeststate(STREAM *s, int request_id)
{
    (void)request_id;
    return s ? s->state : STREAM_STATE_ERROR;
}

void STREAM_setgreedylevel(STREAM *s, int level)
{
    if (s) s->greedy_level = level;
}

void STREAM_setgreedystate(STREAM *s, int state)
{
    (void)state;
}

void STREAM_setpriority(STREAM *s, int priority)
{
    if (s) s->priority = priority;
}

int STREAM_state(STREAM *s)
{
    return s ? s->state : STREAM_STATE_ERROR;
}

void* STREAM_taphandle(STREAM *s, int tap_index)
{
    (void)tap_index;
    return s ? s->buffer : NULL;
}

int STREAM_tapnum(STREAM *s)
{
    return s ? s->num_taps : 0;
}

int STREAM_taprequestid(STREAM *s, int tap_index)
{
    (void)tap_index;
    return 0;
}

/*
 * gluevc.c  —  \real\pc\gluevc.c
 *
 * THRASH dynamic DLL/SO loader.
 * Reconstructed from Porsche.exe embedded strings:
 *   "THRASH_opendll - LOADLIBRARY FAILED ON \"%s\"."
 *   "THRASH_opendll - NO LIBRARY SPECIFIED."
 *   "THRASH_opendll - not a 3rash DLL"
 *   "THRASH_DRIVERNAME"
 *
 * The game calls THRASH_opendll("Drivers/dx7z.dll") at startup.
 * On Linux the driver is "Drivers/openglz.so".
 *
 * Windows: exports are ordinal-only (1-41), loaded via GetProcAddress.
 * Linux:   exports are by name; dlsym("THRASH_init") etc.
 */

#ifdef _WIN32
#  include <windows.h>
#else
#  include "compat/win32_compat.h"
#endif

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../thrash/thrash.h"

/* ------------------------------------------------------------------ */
/*  Global driver module handle                                         */
/* ------------------------------------------------------------------ */
static HMODULE g_hDriver = NULL;

/* ------------------------------------------------------------------ */
/*  Function pointer table (all 41 THRASH exports)                     */
/* ------------------------------------------------------------------ */
typedef const char* (WINAPI *pfn_about)(void);
typedef void        (WINAPI *pfn_void0)(void);
typedef void        (WINAPI *pfn_clip)(int,int,int,int);
typedef int         (WINAPI *pfn_int0)(void);
typedef void*       (WINAPI *pfn_lockwindow)(void);
typedef void        (WINAPI *pfn_readrect)(int,int,int,int,void*);
typedef void        (WINAPI *pfn_selectdisplay)(int);
typedef void        (WINAPI *pfn_setstate)(int,int);
typedef int         (WINAPI *pfn_getstate)(int);
typedef void        (WINAPI *pfn_settexture)(THRASHTEXTURE*);
typedef int         (WINAPI *pfn_setvideomode)(int,int,int);
typedef void        (WINAPI *pfn_sync)(int);
typedef THRASHTEXTURE* (WINAPI *pfn_talloc)(int,int,int,int,void*);
typedef void        (WINAPI *pfn_tfree)(THRASHTEXTURE*);
typedef void        (WINAPI *pfn_tupdate)(THRASHTEXTURE*,void*,int);
typedef void        (WINAPI *pfn_unlockwindow)(int);
typedef void        (WINAPI *pfn_window)(THRASH_HWND);
typedef void        (WINAPI *pfn_writerect)(int,int,int,int,void*);
typedef void        (WINAPI *pfn_drawline)(THRASHVERTEX*,THRASHVERTEX*);
typedef void        (WINAPI *pfn_drawmesh)(int,THRASHVERTEX*,int);
typedef void        (WINAPI *pfn_drawstrip8)(int,THRASHVERTEX*);
typedef void        (WINAPI *pfn_drawpoint)(THRASHVERTEX*);
