    pfn_drawmesh       drawtrifan;
    pfn_drawstrip8     drawtrifan8;
    pfn_drawmesh       drawtrimesh;
    pfn_drawmesh       drawtristrip;
    pfn_drawstrip8     drawtristrip8;
    pfn_void0          flushwindow;
    pfn_getstate       getstate;
