void* getclutptr(void *clut, int clut_type)
{
    if (!clut) return NULL;
    switch (clut_type) {
        case 0x00: /* Standard 256-color 24-bit RGB */
        case 0x20:
            return clut;
        default:
            fprintf(stderr, "getclutptr - UNSUPPORTED CLUT TYPE 0x%x\n", clut_type);
            return clut;
    }
}

void* getclut16ptr(void *clut, int clut_type)
{
    if (!clut) return NULL;
    switch (clut_type) {
        case 0x21: /* 16-bit RGB 555 / 565 */
        case 0x22:
            return clut;
        default:
            fprintf(stderr, "getclut16ptr - UNSUPPORTED CLUT TYPE 0x%x\n", clut_type);
            return clut;
    }
}

void* getclut16aptr(void *clut, int clut_type)
{
    if (!clut) return NULL;
    switch (clut_type) {
        case 0x24: /* 16-bit ARGB 1555 / 4444 */
            return clut;
        default:
            fprintf(stderr, "getclut16aptr - UNSUPPORTED CLUT TYPE 0x%x\n", clut_type);
            return clut;
    }
}

int SHAPE_converttype(void *shape, int src_type, int target_type, int width, int height)
{
    if (!shape) return 0;
    if (src_type == target_type) return 1;

    /* Check sentinels */
    if (width <= 0 || height <= 0) {
        fprintf(stderr, "convshp - SENTINAL CORRUPTED. %dx%dx%d->%dx%dx%d\n",
                width, height, src_type, width, height, target_type);
        return 0;
    }

    /* Support converting 8-bit paletted to 16/32 bit or 16-bit to 32-bit */
    if (src_type == 0x7B && target_type == 0x7D) {
        /* 16-bit to 32-bit conversion */
        return 1;
    }

    fprintf(stderr, "SHAPE_converttype - UNABLE TO CONVERT TO TARGET SHAPE TYPE.\nInitial shape type ($%02x), requested shape type ($%02x)\n",
            src_type, target_type);
    return 0;
}

/* \real\cmn\hlsfile.c */
#include "hlsfile.h"
#include "../../engine/file/vfs.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

uint32_t FILE_size(const char *filename)
{
    FILE *fp = VFS_Open(filename, "rb");
    if (!fp) {
        fprintf(stderr, "FILE_size - unable to open file %s\n", filename);
        return 0;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fclose(fp);
    return (sz > 0) ? (uint32_t)sz : 0;
}

void* FILE_load(const char *filename)
{
    FILE *fp = VFS_Open(filename, "rb");
    if (!fp) {
        fprintf(stderr, "FILE_load - unable to open file %s\n", filename);
        return NULL;
    }

    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    if (sz <= 0) {
        fclose(fp);
        return NULL;
    }

    void *buf = malloc(sz);
    if (!buf) {
        fprintf(stderr, "FILE_load - unable to reserve memory for file %s\n", filename);
        fclose(fp);
        return NULL;
    }

    fread(buf, 1, sz, fp);
    fclose(fp);
    return buf;
}

int FILE_loadat(const char *filename, void *destination)
{
    if (!destination) return 0;
    FILE *fp = VFS_Open(filename, "rb");
    if (!fp) {
        fprintf(stderr, "FILE_loadat - unable to open file %s\n", filename);
        return 0;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    if (sz > 0) {
        fread(destination, 1, sz, fp);
    }
    fclose(fp);
    return 1;
}

int FILE_scatterload(const char *filename, void **destinations, uint32_t *sizes, int count)
{
    if (!filename || !destinations || !sizes || count <= 0) return 0;
    FILE *fp = VFS_Open(filename, "rb");
    if (!fp) {
        fprintf(stderr, "FILE_load - unable to open file %s\n", filename);
        return 0;
    }
    for (int i = 0; i < count; i++) {
        if (destinations[i] && sizes[i] > 0) {
            fread(destinations[i], 1, sizes[i], fp);
        }
    }
    fclose(fp);
    return 1;
}

void FILE_free(void *ptr)
{
    free(ptr);
}

/* \real\cmn\loadshp.c */
#include "loadshp.h"
#include "../../engine/file/vfs.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>

struct SHAPE_Header {
    int count;
    SHAPE_Entry *entries;
    uint8_t *raw;
};

static uint32_t decode_pixel(uint16_t c, int type)
{
    uint32_t a, r, g, b;
    if (type == 0x6D) {
        a = ((c >> 12) & 0xF) * 17;
        r = ((c >> 8) & 0xF) * 17;
        g = ((c >> 4) & 0xF) * 17;
        b = (c & 0xF) * 17;
    } else if (type == 0x7E) {
        a = (c & 0x8000) ? 255 : 0;
        r = ((c >> 10) & 0x1F) * 255 / 31;
        g = ((c >> 5) & 0x1F) * 255 / 31;
        b = (c & 0x1F) * 255 / 31;
    } else {
        a = 255;
        r = ((c >> 11) & 0x1F) * 255 / 31;
        g = ((c >> 5) & 0x3F) * 255 / 63;
        b = (c & 0x1F) * 255 / 31;
    }
    return (a << 24) | (r << 16) | (g << 8) | b;
}

SHAPE_Header* SHAPE_loadfile(const char *filename)
{
    size_t sz = 0;
    uint8_t *buf = (uint8_t*)VFS_ReadFile(filename, &sz);
    if (!buf) {
        fprintf(stderr, "SHAPE_loadfile - UNABLE TO LOAD FILE %s\n", filename);
        return NULL;
    }

    if (sz < 16 || memcmp(buf, "SHPI", 4) != 0) {
        char sig[5] = {0};
        if (sz >= 4) memcpy(sig, buf, 4);
        fprintf(stderr, "SHAPE_loadfile - '%s' UNRECOGNIZED SHAPEFILE SIGNATURE.\nFOUND '%4.4s'. REQUIRES '%s'.  USE GX TO CONVERT?  ie GX %s -fsh\n",
                filename, sig, "SHPI", filename);
        VFS_FreeFile(buf);
        return NULL;
    }

    uint32_t count = *(const uint32_t*)(buf + 8);
    if (count == 0 || count > 4096) {
        VFS_FreeFile(buf);
        return NULL;
    }

    SHAPE_Header *shp = (SHAPE_Header*)calloc(1, sizeof(SHAPE_Header));
    if (!shp) {
        VFS_FreeFile(buf);
        return NULL;
    }

    shp->raw = buf;
    shp->count = count;
    shp->entries = (SHAPE_Entry*)calloc(count, sizeof(SHAPE_Entry));

    for (uint32_t i = 0; i < count; i++) {
        size_t dir_off = 16 + i * 8;
        if (dir_off + 8 > sz) break;

        memcpy(shp->entries[i].name, buf + dir_off, 4);
        shp->entries[i].name[4] = '\0';

        uint32_t rec_off = *(const uint32_t*)(buf + dir_off + 4);
        if (rec_off + 8 > sz) continue;

        uint8_t rec_type = buf[rec_off];
        uint16_t w = *(const uint16_t*)(buf + rec_off + 4);
        uint16_t h = *(const uint16_t*)(buf + rec_off + 6);

        shp->entries[i].width = w;
        shp->entries[i].height = h;
        shp->entries[i].format = rec_type;

        size_t num_pix = (size_t)w * h;
        if (num_pix > 0 && num_pix < 4096 * 4096) {
            shp->entries[i].pixels = (uint32_t*)malloc(num_pix * 4);
            if (shp->entries[i].pixels) {
                if (rec_type == 0x7D) {
                    /* 32-bit direct */
                    memcpy(shp->entries[i].pixels, buf + rec_off + 16, num_pix * 4);
                } else {
                    /* 16-bit packed */
                    const uint16_t *src16 = (const uint16_t*)(buf + rec_off + 16);
                    for (size_t p = 0; p < num_pix; p++) {
                        shp->entries[i].pixels[p] = decode_pixel(src16[p], rec_type);
                    }
                }
            }
        }
    }

    return shp;
}

void SHAPE_free(SHAPE_Header *shp)
{
    if (!shp) return;
    for (int i = 0; i < shp->count; i++) {
        if (shp->entries[i].pixels) free(shp->entries[i].pixels);
    }
    if (shp->entries) free(shp->entries);
    if (shp->raw) VFS_FreeFile(shp->raw);
    free(shp);
}

SHAPE_Entry* SHAPE_findshape(SHAPE_Header *shp, const char *name)
{
    if (!shp || !name) return NULL;
    for (int i = 0; i < shp->count; i++) {
        if (strcasecmp(shp->entries[i].name, name) == 0) {
            return &shp->entries[i];
        }
    }
    return NULL;
}

int SHAPE_getcount(SHAPE_Header *shp)
{
    return shp ? shp->count : 0;
}

SHAPE_Entry* SHAPE_getbyindex(SHAPE_Header *shp, int index)
{
    if (!shp || index < 0 || index >= shp->count) return NULL;
    return &shp->entries[index];
}

